import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

fused_kernel_code = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <math.h>

__global__ void fused_swish_gn_hardswish_kernel(
    const float* input,
    const float* gamma,
    const float* beta,
    float* output,
    int B,
    int C,
    int D,
    int H,
    int W,
    int G,
    float eps,
    int elements_per_group
) {
    int batch = blockIdx.x;
    int group = blockIdx.y;
    int ch_per_group = C / G;

    extern __shared__ float smem[];
    float* sum_smem = smem;
    float* sum_sq_smem = &smem[blockDim.x];

    float sum = 0.0f;
    float sum_sq = 0.0f;
    int tid = threadIdx.x;

    for(int i = tid; i < elements_per_group; i += blockDim.x) {
        int c = group * ch_per_group + (i / (D * H * W)) % ch_per_group;
        int d = (i / (H * W)) % D;
        int h = (i / W) % H;
        int w = i % W;
        int idx = batch*C*D*H*W + c*D*H*W + d*H*W + h*W + w;

        float x = input[idx];
        float swish = x * (1.0f / (1.0f + expf(-x)));
        sum += swish;
        sum_sq += swish * swish;
    }

    sum_smem[tid] = sum;
    sum_sq_smem[tid] = sum_sq;
    __syncthreads();

    for(int s=blockDim.x/2; s>0; s>>=1) {
        if(tid < s) {
            sum_smem[tid] += sum_smem[tid + s];
            sum_sq_smem[tid] += sum_sq_smem[tid + s];
        }
        __syncthreads();
    }

    float mean = sum_smem[0] / elements_per_group;
    float var = (sum_sq_smem[0] / elements_per_group) - (mean * mean);
    float inv_std = rsqrtf(var + eps);

    for(int i = tid; i < elements_per_group; i += blockDim.x) {
        int c = group * ch_per_group + (i / (D * H * W)) % ch_per_group;
        int d = (i / (H * W)) % D;
        int h = (i / W) % H;
        int w = i % W;
        int idx = batch*C*D*H*W + c*D*H*W + d*H*W + h*W + w;

        float x = input[idx];
        float swish = x * (1.0f / (1.0f + expf(-x)));
        float normalized = (swish - mean) * inv_std;
        float y = normalized * gamma[c] + beta[c];
        float hardswish = y * fminf(fmaxf(y + 3.0f, 0.0f), 6.0f) / 6.0f;
        output[idx] = hardswish;
    }
}

torch::Tensor fused_op_cuda(
    torch::Tensor input,
    torch::Tensor gamma,
    torch::Tensor beta,
    int groups,
    float eps
) {
    auto B = input.size(0);
    auto C = input.size(1);
    auto D = input.size(2);
    auto H = input.size(3);
    auto W = input.size(4);
    auto output = torch::empty_like(input);
    int elements_per_group = (C / groups) * D * H * W;

    dim3 grid(B, groups);
    int block = 256;
    size_t smem_size = 2 * block * sizeof(float);

    fused_swish_gn_hardswish_kernel<<<grid, block, smem_size>>>(
        input.data_ptr<float>(),
        gamma.data_ptr<float>(),
        beta.data_ptr<float>(),
        output.data_ptr<float>(),
        B, C, D, H, W, groups, eps, elements_per_group
    );

    return output;
}
"""

fused_kernel_cpp = """
torch::Tensor fused_op_cuda(torch::Tensor input, torch::Tensor gamma, torch::Tensor beta, int groups, float eps);
"""

fused_op = load_inline(
    name='fused_op',
    cpp_sources=fused_kernel_cpp,
    cuda_sources=fused_kernel_code,
    functions=['fused_op_cuda'],
    verbose=True,
    extra_cuda_cflags=['-O3']
)

class ModelNew(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size, stride, padding, groups, eps, bias=True):
        super().__init__()
        self.conv_transpose = nn.ConvTranspose3d(
            in_channels, out_channels, kernel_size,
            stride=stride, padding=padding, bias=bias
        )
        self.groups = groups
        self.eps = eps
        self.gamma = nn.Parameter(torch.ones(out_channels))
        self.beta = nn.Parameter(torch.zeros(out_channels))

    def forward(self, x):
        x = self.conv_transpose(x)
        x = fused_op.fused_op_cuda(x, self.gamma, self.beta, self.groups, self.eps)
        return x
